  function listEligibleQuestTrackerEntries(playerId) {
    const active = [];
    for (const [, def, state, vars, bindings] of world.query(QuestDefRef, QuestState, QuestVars, QuestBindings)) {
      if (String(state?.status || "active") !== "active") continue;
      if (Number(bindings?.player || 0) !== Number(playerId || 0)) continue;
      if (vars?.data?.accepted === false) continue;
      active.push(buildQuestTrackerEntry(def?.id, getQuestDef(def?.id), state, vars));
    }
    return active;
  }

  function pickFocusedQuestTrackerEntry(entries) {
    const active = Array.isArray(entries) ? entries.slice() : [];
    if (activeQuestId) {
      const requested = active.find((entry) => entry.questId === activeQuestId);
      if (requested) return requested;
    }
    active.sort((a, b) => b.priority - a.priority || b.sortKey - a.sortKey || a.title.localeCompare(b.title));
    return active[0] || null;
  }

  function positionOf(entityId) {
    const pos = entityId > 0 ? world.get(entityId, Position) : null;
    return pos ? { x: Number(pos.x) | 0, y: Number(pos.y) | 0 } : null;
  }

  function buildQuestTarget(questId, node, bindings, playerPos, currentDepth, destinationTemplateId = "") {
    const decorate = (target) => target ? { ...target, from: { ...playerPos }, samePlane: Number(target.plane || 0) === currentDepth } : null;
    const giverId = Number(bindings?.giver || 0) | 0;
    if (node === "report") {
      const pos = positionOf(giverId);
      return decorate(pos ? { ...pos, label: "Return to the quest giver", plane: 0, kind: "giver" } : null);
    }

    const entranceMatches = [];
    for (const [id, entrance, pos] of world.query(DungeonEntrance, Position)) {
      const entranceQuestId = String(entrance?.questId || "");
      const entranceTemplateId = String(entrance?.templateId || "");
      if (entranceQuestId !== questId && entranceTemplateId !== destinationTemplateId) continue;
      entranceMatches.push({
        x: Number(pos.x) | 0,
        y: Number(pos.y) | 0,
        label: String(entrance?.label || "Quest entrance"),
        plane: 0,
        kind: "entrance",
        entityId: id,
      });
    }

    if (node === "hunt") {
      const wanted = questId === "side.rootbound_grotto"
        ? new Set(["goblin_mosscaller", "kobold_cairnkeeper", "orc_bloodspeaker", "druid"])
        : questId === "starter.rat_infestation" ? new Set(["rat"]) : null;
      if (wanted && currentDepth > 0) {
        let best = null;
        let bestDistance = Infinity;
