    const tiles = new Array(width * width).fill(-1);
    for (let y = 0; y < width; y++) {
      for (let x = 0; x < width; x++) {
        const wx = x0 + x;
        const wy = y0 + y;
        if (isExplored(wx, wy)) tiles[y * width + x] = Number(getTile(wx, wy) || 0) | 0;
