    count: 1,
  });
  world.add(keyId, Material, { kind: "iron" });
  world.add(keyId, DoorKey, { lockId: RAT_CELLAR_LOCK_ID });
  return addToInventory(world, actorId, keyId) ? keyId : 0;
}

function currentDownStairPos(world) {
